CREATE TABLE inventory (
  product_id BIGINT UNSIGNED NOT NULL,
  stock INT NOT NULL DEFAULT 0,
  version INT NOT NULL DEFAULT 0,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (product_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT INTO inventory (product_id, stock, version) VALUES (1, 100, 0)
ON DUPLICATE KEY UPDATE stock = 100, version = 0;

-- 事务 A 与事务 B 同时执行下面两步，观察结果
SELECT stock FROM inventory WHERE product_id = 1;
-- 应用层判断 stock >= 1 后执行：
UPDATE inventory SET stock = stock - 1 WHERE product_id = 1;

SELECT stock FROM inventory WHERE product_id = 1;

START TRANSACTION;

UPDATE inventory
SET stock = stock - 1, version = version + 1
WHERE product_id = 1
  AND stock >= 1;

-- 影响 1 行 = 扣减成功；影响 0 行 = 库存不足，直接回滚
SELECT ROW_COUNT() AS affected_rows;

COMMIT;

SELECT stock, version FROM inventory WHERE product_id = 1;
-- 假设读到 stock = 99, version = 5

UPDATE inventory
SET stock = 99 - 1, version = version + 1
WHERE product_id = 1
  AND version = 5
  AND stock >= 1;

SELECT ROW_COUNT() AS affected_rows;

-- 会话 1
START TRANSACTION;
SELECT stock FROM inventory WHERE product_id = 1 FOR UPDATE;
UPDATE inventory SET stock = stock - 1 WHERE product_id = 1 AND stock >= 1;
COMMIT;

-- 会话 2（会话 1 未提交时会在这里等锁）
SELECT stock FROM inventory WHERE product_id = 1 FOR UPDATE;

SELECT product_id, stock, version
FROM inventory
WHERE product_id = 1;

-- 兜底校验：任何一行都不该为负
SELECT product_id, stock FROM inventory WHERE stock < 0;

-- 对账：成功订单的扣减总量 = 初始库存 - 当前库存
SELECT COUNT(*) AS success_cnt, SUM(quantity) AS sold_qty
FROM order_items oi
JOIN orders o ON o.id = oi.order_id
WHERE oi.product_id = 1 AND o.status IN (1, 2, 3);

CREATE TABLE idempotency_record (
  token VARCHAR(64) NOT NULL,
  order_id BIGINT UNSIGNED DEFAULT NULL,
  status TINYINT NOT NULL DEFAULT 0 COMMENT '0处理中 1已完成',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (token),
  KEY idx_order (order_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ALTER TABLE orders ADD UNIQUE KEY uk_order_no (order_no);

START TRANSACTION;

INSERT INTO idempotency_record (token, status) VALUES ('req-20261110-0001', 0);

INSERT INTO orders (order_no, user_id, status, total_amount)
VALUES ('ORD202611100001', 1, 0, 598.00);

SELECT LAST_INSERT_ID() AS new_order_id;
-- 假设返回 1
UPDATE idempotency_record SET order_id = 1, status = 1 WHERE token = 'req-20261110-0001';

COMMIT;

-- 第二次请求，会报 ERROR 1062 (23000): Duplicate entry
INSERT INTO idempotency_record (token, status) VALUES ('req-20261110-0001', 0);

-- 幂等处理：冲突后读已有记录，直接返回
SELECT token, order_id, status
FROM idempotency_record
WHERE token = 'req-20261110-0001';

INSERT INTO inventory (product_id, stock)
VALUES (1, 100)
ON DUPLICATE KEY UPDATE
  stock = stock + VALUES(stock);

SELECT ROW_COUNT() AS affected_rows;

-- 会话 A
START TRANSACTION;
INSERT INTO idempotency_record (token, status) VALUES ('req-concurrent-001', 0);

-- 会话 B 同时执行同一句，会报 Duplicate entry（或等待 A 提交后报错）
-- INSERT INTO idempotency_record (token, status) VALUES ('req-concurrent-001', 0);

-- 校验：这个 token 只有一条记录
SELECT COUNT(*) AS token_cnt FROM idempotency_record WHERE token = 'req-concurrent-001';

