-- 路由规则：user_id % 4 决定分片
SELECT 12345 % 4 AS shard_index;

-- 创建 4 张分片表（结构用 LIKE 复制，先不加外键，跨片外键无意义）
CREATE TABLE orders_0 LIKE orders;
CREATE TABLE orders_1 LIKE orders;
CREATE TABLE orders_2 LIKE orders;
CREATE TABLE orders_3 LIKE orders;

-- 分片表上把唯一键改成「(user_id, order_no)」以适配跨片
ALTER TABLE orders_0 DROP INDEX uk_order_no,
  ADD UNIQUE KEY uk_user_order_no (user_id, order_no);
ALTER TABLE orders_1 DROP INDEX uk_order_no,
  ADD UNIQUE KEY uk_user_order_no (user_id, order_no);
ALTER TABLE orders_2 DROP INDEX uk_order_no,
  ADD UNIQUE KEY uk_user_order_no (user_id, order_no);
ALTER TABLE orders_3 DROP INDEX uk_order_no,
  ADD UNIQUE KEY uk_user_order_no (user_id, order_no);

