-- 双写阶段：同一次下单写两张表（同一事务内，或由 binlog 同步任务保证）
START TRANSACTION;
INSERT INTO orders (order_no, user_id, status, total_amount)
VALUES ('ORD202611100999', 12345, 0, 299.00);
INSERT INTO orders_1 (order_no, user_id, status, total_amount)
