-- 切换：老表改名为备份表（保留回滚能力）
RENAME TABLE orders TO orders_bak;

-- 回滚（新链路异常时执行）
RENAME TABLE orders_bak TO orders;

-- 确认各分片数据量与老表一致
SELECT 'orders_0' AS shard, COUNT(*) AS cnt FROM orders_0
UNION ALL SELECT 'orders_1', COUNT(*) FROM orders_1
UNION ALL SELECT 'orders_2', COUNT(*) FROM orders_2
UNION ALL SELECT 'orders_3', COUNT(*) FROM orders_3;
